require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/session.php';require_once __DIR__.'/../../includes/functions.php';require_once __DIR__.'/../../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../../index.php');
$eventId=(int)($_GET['event_id']??$_POST['event_id']??0);$sessionId=(int)($_GET['session_id']??$_POST['session_id']??0);$message='';$error='';$events=pg_query($conn,"SELECT id,title,start_at,status FROM events WHERE status IN ('open','ongoing','completed') ORDER BY CASE WHEN status='ongoing' THEN 0 ELSE 1 END,start_at DESC");if(!$eventId&&$events&&pg_num_rows($events))$eventId=(int)pg_fetch_result($events,0,'id');$event=null;if($eventId){$r=pg_query_params($conn,'SELECT * FROM events WHERE id=$1',[$eventId]);$event=$r&&pg_num_rows($r)?pg_fetch_assoc($r):null;}
$sessions=$event?pg_query_params($conn,'SELECT * FROM event_sessions WHERE event_id=$1 ORDER BY id',[$eventId]):null;if(!$sessionId&&$sessions&&pg_num_rows($sessions))$sessionId=(int)pg_fetch_result($sessions,0,'id');$session=null;if($sessionId){$r=pg_query_params($conn,'SELECT * FROM event_sessions WHERE id=$1 AND event_id=$2',[$sessionId,$eventId]);$session=$r&&pg_num_rows($r)?pg_fetch_assoc($r):null;}
function scan_window_error($conn,$sessionId,$mode){$start=$mode==='time_out'?'time_out_start':'time_in_start';$end=$mode==='time_out'?'time_out_end':'time_in_end';$r=pg_query_params($conn,"SELECT $start window_start,$end window_end,NOW() local_now FROM event_sessions WHERE id=$1",[$sessionId]);if(!$r||!pg_num_rows($r))return 'Attendance session was not found.';$w=pg_fetch_assoc($r);$now=strtotime($w['local_now']);if($w['window_start']&&$now<strtotime($w['window_start']))return ucfirst(str_replace('_','-',$mode)).' is not open yet. It opens '.date('M j, Y g:i A',strtotime($w['window_start'])).'.';if($w['window_end']&&$now>strtotime($w['window_end']))return ucfirst(str_replace('_','-',$mode)).' window closed '.date('M j, Y g:i A',strtotime($w['window_end'])).'. Ask an administrator to use the audited manual override if appropriate.';return '';}
if($_SERVER['REQUEST_METHOD']==='POST'&&$event){
 if(!verify_csrf_token($_POST['csrf_token']??''))$error='Security token expired.';else{$action=$_POST['action']??'';
  if($action==='lookup'){$code=strtoupper(trim($_POST['code']??''));$qr=str_starts_with($code,'AMS:')?substr($code,4):$code;$r=pg_query_params($conn,"SELECT r.id registration_id,r.status,a.full_name,a.attendee_code FROM event_registrations r JOIN attendees a ON a.id=r.attendee_id WHERE r.event_id=$1 AND (upper(r.ticket_code)=$2 OR upper(a.attendee_code)=$2 OR upper(a.id_card_number)=$2 OR upper(a.qr_token)=$3) LIMIT 1",[$eventId,$code,$qr]);if(!$r||!pg_num_rows($r))$error='No event registration matches that QR, student ID, ID card, or ticket code.';else{$row=pg_fetch_assoc($r);if($row['status']!=='registered')$error='This registration is '.$row['status'].' and cannot record attendance.';elseif($session&&$session['status']!=='open')$error='This attendance session is not open.';elseif($session){$mode=($_POST['scan_mode']??'time_in')==='time_out'?'time_out':'time_in';$error=scan_window_error($conn,$sessionId,$mode);$evidence=null;$face=null;if(!$error&&$event['require_photo_evidence']==='t'){$face=($_POST['face_detected']??'')==='1';if(!$face)$error='A visible face was not detected. Reposition the student and scan again.';else $evidence=save_attendance_evidence($_POST['evidence_photo']??'','session-'.$sessionId,$error);}if(!$error){if($mode==='time_in'){$ok=pg_query_params($conn,"INSERT INTO session_attendance(session_id,registration_id,time_in_at,time_in_evidence,time_in_face_detected,time_in_by) VALUES($1,$2,NOW(),$3,$4,$5) ON CONFLICT(session_id,registration_id) DO UPDATE SET time_in_at=COALESCE(session_attendance.time_in_at,NOW()),time_in_evidence=COALESCE(session_attendance.time_in_evidence,EXCLUDED.time_in_evidence),time_in_face_detected=COALESCE(session_attendance.time_in_face_detected,EXCLUDED.time_in_face_detected),time_in_by=COALESCE(session_attendance.time_in_by,EXCLUDED.time_in_by),updated_at=NOW()",[$sessionId,$row['registration_id'],$evidence,$face,$_SESSION['admin_id']]);$message=$row['full_name'].' time-in recorded for '.ucfirst($session['session_name']).'.';}else{$ok=pg_query_params($conn,"INSERT INTO session_attendance(session_id,registration_id,time_out_at,time_out_evidence,time_out_face_detected,time_out_by) VALUES($1,$2,NOW(),$3,$4,$5) ON CONFLICT(session_id,registration_id) DO UPDATE SET time_out_at=COALESCE(session_attendance.time_out_at,NOW()),time_out_evidence=COALESCE(session_attendance.time_out_evidence,EXCLUDED.time_out_evidence),time_out_face_detected=COALESCE(session_attendance.time_out_face_detected,EXCLUDED.time_out_face_detected),time_out_by=COALESCE(session_attendance.time_out_by,EXCLUDED.time_out_by),updated_at=NOW()",[$sessionId,$row['registration_id'],$evidence,$face,$_SESSION['admin_id']]);$message=$row['full_name'].' time-out recorded for '.ucfirst($session['session_name']).'.';}audit_log($conn,'session_'.$mode,'event_session',$sessionId,['registration_id'=>$row['registration_id'],'photo_evidence'=>(bool)$evidence]);}}
    else{$ok=pg_query_params($conn,"INSERT INTO attendance_records(registration_id,check_in_method,recorded_by) VALUES($1,'scan',$2) ON CONFLICT DO NOTHING",[$row['registration_id'],$_SESSION['admin_id']]);$message=pg_affected_rows($ok)?$row['full_name'].' checked in.':'Attendance already exists.';}}
  }elseif($action==='manual'&&$session&&($registrationId=(int)($_POST['registration_id']??0))){$mode=($_POST['scan_mode']??'time_in')==='time_out'?'time_out':'time_in';if($mode==='time_in')pg_query_params($conn,"INSERT INTO session_attendance(session_id,registration_id,time_in_at,time_in_by) VALUES($1,$2,NOW(),$3) ON CONFLICT(session_id,registration_id) DO UPDATE SET time_in_at=COALESCE(session_attendance.time_in_at,NOW()),time_in_by=COALESCE(session_attendance.time_in_by,$3),updated_at=NOW()",[$sessionId,$registrationId,$_SESSION['admin_id']]);else pg_query_params($conn,"INSERT INTO session_attendance(session_id,registration_id,time_out_at,time_out_by) VALUES($1,$2,NOW(),$3) ON CONFLICT(session_id,registration_id) DO UPDATE SET time_out_at=COALESCE(session_attendance.time_out_at,NOW()),time_out_by=COALESCE(session_attendance.time_out_by,$3),updated_at=NOW()",[$sessionId,$registrationId,$_SESSION['admin_id']]);audit_log($conn,'manual_session_'.$mode,'event_session',$sessionId,['registration_id'=>$registrationId]);$message='Manual '.str_replace('_','-',$mode).' recorded.';}
 }
}
$q=trim($_GET['q']??'');$params=[$eventId];$filter='';if($q!==''){$params[]='%'.$q.'%';$filter=' AND (a.full_name ILIKE $2 OR a.attendee_code ILIKE $2 OR r.ticket_code ILIKE $2)';}$join=$session?'LEFT JOIN session_attendance sa ON sa.registration_id=r.id AND sa.session_id='.(int)$sessionId:'LEFT JOIN attendance_records sa ON sa.registration_id=r.id';$in=$session?'sa.time_in_at':'sa.check_in_at';$out=$session?'sa.time_out_at':'sa.check_out_at';$rows=$event?pg_query_params($conn,"SELECT r.id registration_id,r.ticket_code,r.status,a.full_name,a.attendee_code,a.organization,$in time_in_at,$out time_out_at FROM event_registrations r JOIN attendees a ON a.id=r.attendee_id $join WHERE r.event_id=$1 $filter ORDER BY $in DESC NULLS LAST,a.full_name",$params):null;$stats=$event?pg_query_params($conn,"SELECT COUNT(*) FILTER(WHERE r.status='registered') registered,COUNT($in) present,COUNT(*) FILTER(WHERE $in IS NOT NULL AND $out IS NULL) inside,COUNT($out) departed FROM event_registrations r $join WHERE r.event_id=$1",[$eventId]):null;$sum=$stats?pg_fetch_assoc($stats):['registered'=>0,'present'=>0,'inside'=>0,'departed'=>0];admin_page_start('Check-in Desk','attendance');?>
<div class="hero"><div><h2><i class="fas fa-qrcode"></i> Session Check-in Desk</h2><p>Scan permanent student QR or ID cards with optional face-presence evidence.</p></div></div><?php if($message):?><div class="alert"><?=h($message)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?>
