<div class="card"><h3>Camera QR Scanner <?=$event['require_photo_evidence']==='t'?'· Face Evidence Required':''?></h3><div class="grid two-col"><div><div id="qrReader" style="max-width:430px"></div><button type="button" class="btn secondary" id="startScanner"><i class="fas fa-camera"></i> Open Camera Scanner</button><canvas id="evidenceCanvas" hidden></canvas></div><form method="post" class="form-grid" id="lookupForm"><?=csrf_field()?><input type="hidden" name="event_id" value="<?=$eventId?>"><input type="hidden" name="session_id" value="<?=$sessionId?>"><input type="hidden" name="action" value="lookup"><input type="hidden" name="evidence_photo" id="evidencePhoto"><input type="hidden" name="face_detected" id="faceDetected"><div class="field"><label>Scan action</label><select name="scan_mode"><option value="time_in">Time In</option><option value="time_out">Time Out</option></select></div><div class="field full"><label>QR, ticket, or student ID</label><div class="actions"><input name="code" id="attendanceCode" required autocomplete="off"><button class="btn">Record</button></div><p class="help">Manual roster controls below are an administrator override and do not create photo evidence.</p></div></form></div></div>
<div class="card"><div class="panel-header"><h3><?=h($event['title'])?> · <?=h($session?ucfirst($session['session_name']).' Session':'Event Roster')?></h3></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Ticket</th><th>Time-in</th><th>Time-out</th><th>Manual Override</th></tr></thead><tbody><?php if($rows):while($a=pg_fetch_assoc($rows)):?><tr><td><strong><?=h($a['full_name'])?></strong><div class="help"><?=h($a['attendee_code'])?> · <?=h($a['organization']?:'—')?></div></td><td><?=h($a['ticket_code'])?></td><td><?=$a['time_in_at']?h(date('M j, g:i:s A',strtotime($a['time_in_at']))):'—'?></td><td><?=$a['time_out_at']?h(date('M j, g:i:s A',strtotime($a['time_out_at']))):'—'?></td><td><?php if($session):?><div class="actions"><?php foreach(['time_in'=>'Time In','time_out'=>'Time Out'] as $mode=>$label):?><form method="post"><?=csrf_field()?><input type="hidden" name="event_id" value="<?=$eventId?>"><input type="hidden" name="session_id" value="<?=$sessionId?>"><input type="hidden" name="registration_id" value="<?=(int)$a['registration_id']?>"><input type="hidden" name="action" value="manual"><button class="btn small secondary" name="scan_mode" value="<?=$mode?>"><?=$label?></button></form><?php endforeach;?></div><?php else:?>Configure sessions first<?php endif;?></td></tr><?php endwhile;endif;if(!$rows||pg_num_rows($rows)===0):?><tr><td colspan="5" class="empty">No registrations found.</td></tr><?php endif;?></tbody></table></div></div><?php endif;?>
<script src="https://cdnjs.cloudflare.com/ajax/libs/html5-qrcode/2.3.8/html5-qrcode.min.js"></script><script>const evidenceRequired=<?=$event&&$event['require_photo_evidence']==='t'?'true':'false'?>;let attendanceScanner=null,scanBusy=false;async function finishScan(text){if(scanBusy)return;scanBusy=true;const video=document.querySelector('#qrReader video');if(evidenceRequired){if(!video||!video.videoWidth){alert('Camera frame is not ready. Scan again.');scanBusy=false;return}const c=document.getElementById('evidenceCanvas'),max=720,scale=Math.min(1,max/video.videoWidth);c.width=Math.round(video.videoWidth*scale);c.height=Math.round(video.videoHeight*scale);c.getContext('2d').drawImage(video,0,0,c.width,c.height);if(!('FaceDetector'in window)){alert('This browser cannot perform on-device face detection. Use current Chrome/Edge or a manual administrator override.');scanBusy=false;return}try{const faces=await new FaceDetector({fastMode:true,maxDetectedFaces:3}).detect(c);if(!faces.length){alert('No visible face detected. Ask the student to face the camera and scan again.');scanBusy=false;return}document.getElementById('faceDetected').value='1';document.getElementById('evidencePhoto').value=c.toDataURL('image/jpeg',.76)}catch(e){alert('Face detection failed. Please scan again.');scanBusy=false;return}}document.getElementById('attendanceCode').value=text;await attendanceScanner.clear();document.getElementById('lookupForm').submit()}document.getElementById('startScanner')?.addEventListener('click',function(){if(attendanceScanner)return;attendanceScanner=new Html5QrcodeScanner('qrReader',{fps:10,qrbox:{width:240,height:240},rememberLastUsedCamera:true},false);attendanceScanner.render(finishScan,function(){})});</script><?php admin_page_end();?>
